target.css:
:root {
  --paper: #fffdf7;
  --ink: #243747;
  --muted: #71808a;
  --line: #d9e1df;
  --navy: #294c60;
  --blue: #4e91a8;
  --aqua: #9fd6d0;
  --aqua-soft: #e4f3ef;
  --amber: #d8953f;
  --amber-soft: #fff0d7;
  --white: #ffffff;
}

.console {
  width: 480px;
  box-sizing: border-box;
  overflow: hidden;
  background: var(--paper);
  border: 1px solid var(--line);
  border-radius: 16px;
  color: var(--ink);
}

.console * {
  box-sizing: border-box;
}

.console-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 11px 15px;
  border-bottom: 1px solid var(--line);
}

.eyebrow {
  margin: 0;
  color: var(--muted);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.09em;
  line-height: 1.2;
  text-transform: uppercase;
}

h1, h2, p {
  margin: 0;
}

h1 {
  margin-top: 3px;
  font-size: 18px;
  line-height: 1.1;
  letter-spacing: -0.03em;
}

.state {
  padding: 5px 8px;
  border-radius: 999px;
  background: var(--aqua-soft);
  color: var(--navy);
  font-size: 10px;
  font-weight: 700;
}

.workspace {
  display: grid;
  grid-template-columns: 1.03fr 1.27fr;
  gap: 12px;
  padding: 12px 15px;
}

.reading {
  padding: 11px;
  border-radius: 11px;
  background: var(--navy);
  color: var(--white);
}

.reading .eyebrow {
  color: var(--aqua);
}

.lux {
  margin-top: 5px;
  font-size: 28px;
  font-weight: 750;
  line-height: 0.9;
  letter-spacing: -0.06em;
}

.unit {
  color: var(--aqua);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0;
}

.meter {
  height: 6px;
  margin: 11px 0 7px;
  overflow: hidden;
  border-radius: 99px;
  background: var(--blue);
}

.meter-fill {
  display: block;
  width: 94%;
  height: 100%;
  border-radius: inherit;
  background: var(--amber);
}

.note {
  color: var(--aqua);
  font-size: 9px;
  font-weight: 600;
  line-height: 1.2;
}

.details {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 6px;
}

.detail {
  min-height: 48px;
  padding: 8px 9px;
  border: 1px solid var(--line);
  border-radius: 9px;
}

.detail-label {
  margin-bottom: 4px;
  color: var(--muted);
  font-size: 9px;
  line-height: 1.1;
}

.detail-value {
  color: var(--navy);
  font-size: 14px;
  font-weight: 750;
  line-height: 1;
  letter-spacing: -0.03em;
}

.detail-value span {
  color: var(--muted);
  font-size: 9px;
  font-weight: 600;
  letter-spacing: 0;
}

.timeline {
  margin: 0 15px;
  padding: 9px 0 10px;
  border-top: 1px solid var(--line);
}

.timeline-head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  margin-bottom: 6px;
}

h2 {
  font-size: 11px;
  line-height: 1;
}

.timeline-head p {
  color: var(--muted);
  font-size: 9px;
}

.times {
  display: flex;
  gap: 5px;
}

.time {
  flex: 1;
  padding: 3px 0;
  border-radius: 5px;
  background: var(--aqua-soft);
  color: var(--muted);
  font-size: 8px;
  font-weight: 700;
  line-height: 1.1;
  text-align: center;
}

.time b {
  color: var(--navy);
  font-size: 10px;
}

.time.active {
  background: var(--amber-soft);
  outline: 1px solid var(--amber);
}

footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 8px 15px;
  background: var(--aqua-soft);
}

.location {
  color: var(--navy);
  font-size: 10px;
  font-weight: 700;
}

.calibrate {
  padding: 6px 9px;
  border: 0;
  border-radius: 6px;
  background: var(--navy);
  color: var(--white);
  font-size: 10px;
  font-weight: 700;
  line-height: 1.1;
}

